def get_logical_path_map(inventory: dict, version: str) -> dict:
    """
    Returns a dictionary mapping state names to their corresponding file paths for the specified version.

    Args:
        inventory (dict): A dictionary containing state names as keys and lists of file paths as values.
        version (str): A string representing the desired version.

    Returns:
        dict: A dictionary where the keys are state names and the values are the file paths associated with those states for the specified version.

    Raises:
        ValueError: If the inventory is empty or the version does not exist in the inventory.
    """
    if not inventory:
        raise ValueError("Inventory is empty")

    if version not in inventory:
        raise ValueError(f"Version {version} does not exist in the inventory")

    return {state: paths.get(version, []) for state, paths in inventory.items()}


