from typing import List
import zipfile
import os


def files_list_from_zipfile(zip_path: str) -> List[str]:
    """List all files in a zip archive.

    Args:
        zip_path (str): The path to the zip file.

    Returns:
        List[str]: A list of filenames in the zip archive.

    Raises:
        FileNotFoundError: If the zip file does not exist.
        zipfile.BadZipFile: If the zip file is corrupted or invalid.
    """
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_file:
            return zip_file.namelist()
    except FileNotFoundError:
        raise FileNotFoundError(f"The file at {zip_path} does not exist.")
    except zipfile.BadZipFile:
        raise zipfile.BadZipFile(f"The file at {zip_path} is not a valid zip file.")


def main():
    """Main function to demonstrate the usage of files_list_from_zipfile."""
    zip_path = "example.zip"
    if os.path.exists(zip_path):
        try:
            file_list = files_list_from_zipfile(zip_path)
            print("Files in the zip archive:")
            for file_name in file_list:
                print(file_name)
        except Exception as e:
            print(f"An error occurred: {e}")
    else:
        print(f"The file {zip_path} does not exist.")


if __name__ == "__main__":
    main()

