def register_vcs_handler(vcs: str) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    """Decorator function to register methods as handlers for specific VCS types."""
    handlers = {}

    def decorator(method: Callable[..., Any]) -> Callable[..., Any]:
