from typing import List, Dict

def _dictsum(dicts: List[Dict[str, int]]) -> Dict[str, int]:
    """
    Sum the values of keys that appear in more than one dictionary in the list.

    Args:
        dicts (List[Dict[str, int]]): A list of dictionaries containing string keys and integer values.

    Returns:
        Dict[str, int]: A dictionary with keys that appear in more than one dictionary and their summed values.
    """
    # Initialize an empty dictionary to store the sum of values
    result = {}

    # Iterate over each dictionary in the list
    for dictionary in dicts:
        # Iterate over each key-value pair in the current dictionary
        for key, value in dictionary.items():
            # If the key already exists in the result dictionary, add the value to the existing value
            if key in result:
                result[key] += value
            else:
                # Otherwise, initialize the key with the value
                result[key] = value

    # Filter out keys that only appeared once by checking their presence in more than one dictionary
    filtered_result = {key: value for key, value in result.items() if sum(key in d for d in dicts) > 1}

    return filtered_result


# Example usage
